# We want to find the 3 highest intensity peaks in ps_clean.csv
# Assuming files are already injected into the environment
for f in files:
    if f['filename'] == 'ps_clean.csv':
        target_file = f
        break

if target_file is None:
    print("File ps_clean.csv not found in injected files.")
else:
    table = target_file['table']
    cols = target_file['columns']
    print(f"Columns: {cols}")

    # Identify Raman shift and Intensity columns
    # Common names are 'raman_shift', 'shift', 'intensity', 'counts'
    x_col = None
    y_col = None
    for col in cols:
        if 'shift' in col.lower() or 'cm-1' in col.lower():
            x_col = col
        elif 'int' in col.lower() or 'count' in col.lower():
            y_col = col

    if x_col and y_col:
        x = table[x_col]
        y = table[y_col]

        # Find peaks. A simple way is to find local maxima.
        # Since it's a 'clean' spectrum, we can look for the absolute highest points
        # and their corresponding X values. 
        # However, the user wants "peaks", which typically means local maxima.

        peaks = []
        for i in range(1, len(y) - 1):
            if y[i] > y[i-1] and y[i] > y[i+1]:
                peaks.append((x[i], y[i]))

        # Sort peaks by intensity descending
        peaks.sort(key=lambda p: p[1], reverse=True)

        print("Top 3 Peaks:")
        for i in range(min(3, len(peaks))):
            print(f"{i+1}. Position: {peaks[i][0]:.2f} cm-1, Intensity: {peaks[i][1]:.2f}")
    else:
        print("Could not identify Raman shift and intensity columns.")

